// waf-report.sh の結果から「短時間に同じ IP から遮断が集中している」ものだけを拾う。
//
// 判定とメール本文の組み立てだけをここに置いている (集計はスクリプト側)。
// n8n でやる理由は 2 つ:
//   - 前回いつ通知したかを保持できる ($getWorkflowStaticData)。
//     同じスキャナで毎時間メールが来ると、そのうち誰も読まなくなる。
//   - 閾値やクールダウンをワークフローの編集だけで変えられる。
const threshold = Number($env.WAF_ALERT_THRESHOLD || 30);
const cooldownHours = Number($env.WAF_ALERT_COOLDOWN_HOURS || 6);

const raw = $input.first().json.stdout || '';
let report;
try {
  report = JSON.parse(raw);
} catch (e) {
  // JSON として読めない = スクリプトが壊れている。黙って止まらないよう例外にする。
  throw new Error('waf-report.sh の出力を JSON として読めません: ' + raw.slice(0, 300));
}

const hits = (report.top_ips || []).filter((r) => Number(r.count) >= threshold);

// 通知済みの IP はクールダウンの間スキップする
const state = $getWorkflowStaticData('global');
state.notified = state.notified || {};
const now = Date.now();
const cooldownMs = cooldownHours * 3600 * 1000;
const fresh = hits.filter((h) => !state.notified[h.ip] || now - state.notified[h.ip] > cooldownMs);
for (const h of fresh) state.notified[h.ip] = now;

// 1 週間触れていない記録は捨てる (静的データが際限なく太らないように)
for (const ip of Object.keys(state.notified)) {
  if (now - state.notified[ip] > 7 * 24 * 3600 * 1000) delete state.notified[ip];
}

// 該当なしならここで終わり。後続のメールノードは実行されない。
if (fresh.length === 0) return [];

const w = report.window || {};
const s = report.summary || {};
const lines = fresh.map((h) => '  ' + h.ip + '  ' + h.count + ' 件');
const uris = (report.top_uris || []).slice(0, 5).map((u) => '  ' + u.uri + '  ' + u.count + ' 件');

const text = [
  'WAF (ModSecurity) が同一 IP からのリクエストを集中的に遮断しています。',
  '',
  '集計範囲 : 直近 ' + (w.hours || 1) + ' 時間 (' + (w.since || '') + ' 以降, ' + (w.log_tz || '') + ')',
  '遮断件数 : ' + (s.blocked || 0) + ' 件 / 攻撃元 ' + (s.unique_ips || 0) + ' IP',
  '閾値     : 1 IP あたり ' + threshold + ' 件以上 (同じ IP は ' + cooldownHours + ' 時間再通知しない)',
  '',
  '■ 閾値を超えた IP',
  ...lines,
  '',
  '■ この時間に狙われた URI',
  ...uris,
  '',
  '■ 確認のしかた',
  '  BAN されているか   : fail2ban-client status nginx-modsecurity',
  '  手動で BAN する    : fail2ban-client set nginx-modsecurity banip <IP>',
  '  詳しい内容を見る   : platform/scripts/waf-report.sh --hours 1 --recent 30',
  '',
  '(fail2ban の nginx-modsecurity は 10 分間に 15 回で 24 時間 BAN。',
  ' それでも遮断が続く場合は、BAN 解除待ちの再開かサブネットを変えた再試行の可能性があります)',
].join('\n');

return [
  {
    json: {
      subject: 'WAF: ' + fresh.map((h) => h.ip).join(', ') + ' からの遮断が閾値を超えました',
      text,
      threshold,
      ips: fresh,
    },
  },
];
